import {json,allItems,category} from '../data.js';
import {heading,target,audioButtons,esc,modal} from '../ui.js';
import {availableVoices,updateVoices,downloadAudio} from '../audio.js';
import {startQuiz} from './study.js';
import {shuffle} from '../srs.js';
export async function alphabet(c){const rows=await json(`data/${c.language.code}/alphabet.json`);c.register(rows);c.store.lang().alphabetExplored=true;c.store.save();const ar=c.language.code==='ar';view().innerHTML=heading(ar?'A whole new way to write.':'Find the sound of Italian.',ar?'28 letters. Written right to left. A beautiful place to begin.':'Meet the letters, then listen for the little differences.')+`<div class="toolbar"><button class="button secondary" id="recognition">Play letter recognition</button>${ar?'<button class="button secondary" id="forms-game">Identify a letter form</button><button class="button secondary" id="connect-game">Build words from letters</button><button class="button secondary" id="legend">Pronunciation legend</button>':''}<a class="button secondary" href="#/${c.language.code}/grammar">${ar?'Vowels, special letters & sun/moon letters':'Pronunciation in context'} →</a></div>${ar?'<p class="banner">The six letters ا د ذ ر ز و do not connect to the letter that follows them. Select a letter to see its four written forms. Audio reads the letter name; its exact consonant sound is described in the guide.</p>':`<section class="card" style="margin-bottom:20px"><h2>The Italian alphabet</h2><div class="keybar">${Array.from('ABCDEFGHILMNOPQRSTUVZ').map((x,i)=>`<button data-alpha="${i}">${x}</button>`).join('')}</div><p class="muted">21 core letters. J, K, W, X, and Y occur mainly in borrowed words and names.</p></section>`}<div class="${ar?'alphabet':'grid2'}">${rows.map((x,i)=>ar?`<button class="card letter" data-letter="${i}"><b dir="rtl" lang="ar">${esc(x.target)}</b><strong>${esc(x.name)}</strong><small>${esc(x.transliteration)} ${x.nonConnecting?'· stops connection':''}</small></button>`:`<section class="card"><h2>${esc(x.target)}</h2><p>${esc(x.notes)}</p><div class="large">${esc(x.example.target)}</div>${audioButtons(x.id)}</section>`).join('')}</div><section class="card" style="margin-top:20px"><h2>${ar?'A beginner’s reading note':'A little stress goes a long way'}</h2><p>${ar?'Arabic short vowels sit above or below letters. Turn diacritics on in Settings when starting out. Letter shapes vary with their position; the forms here use visible connecting strokes to show that relationship. This is MSA, with provisional pronunciation guides awaiting native review.':'Italian spelling is consistent, but stress is not always written. Final stressed vowels carry an accent: città, caffè, perché. Length matters: pena (penalty) and penna (pen), caro (dear) and carro (cart). Listen slowly, then say each pair aloud.'}</p></section>`;
if(!ar){const names=['a','bi','ci','di','e','effe','gi','acca','i','elle','emme','enne','o','pi','cu','erre','esse','ti','u','vu','zeta'];for(const b of document.querySelectorAll('[data-alpha]'))b.onclick=()=>{const i=Number(b.dataset.alpha);const item={id:'it-alpha-'+i,target:names[i]};c.audio.speak(item,c.language,false,c.toast);};for(const x of rows)x.target=x.example.target;}
for(const b of document.querySelectorAll('[data-letter]'))b.onclick=()=>{const x=rows[Number(b.dataset.letter)];const spoken={...x,id:x.id+'-name',target:x.name==='alif'?'أَلِف':x.target};c.register([spoken]);modal(`<h2>${esc(x.name)} · ${target(x,c.language)}</h2><p>${esc(x.notes)}</p><p class="muted">Isolated · Initial · Medial · Final</p><div class="forms" dir="ltr">${x.forms.map(f=>`<bdi dir="rtl">${esc(f)}</bdi>`).join(' ')}</div>${audioButtons(spoken.id)}<p>Example: ${target(x.example,c.language)} · ${esc(x.example.native)}</p>`);};
document.querySelector('#legend')?.addEventListener('click',()=>modal('<h2>A simple pronunciation legend</h2><p>aa, ii, uu = long vowels · kh = خ · sh = ش · gh = غ · th = ث · dh = ذ · H = ح · S = ص · D = ض · T = ط · DH = ظ · ʿ = ع · ʾ = ء.</p><p>The Arabic guides in this seed library are provisional, mechanically transliterated aids. Shadda and unwritten vowels need native review. Use installed Arabic audio or a native recording as the pronunciation reference.</p>'));
document.querySelector('#recognition').onclick=()=>startQuiz(c,{items:rows.map(x=>({...x,target:ar?x.target:x.example.target,native:ar?x.name:x.target})),types:['choice','listen'],questionCount:10});document.querySelector('#forms-game')?.addEventListener('click',()=>startQuiz(c,{items:rows.map((x,i)=>({...x,id:x.id+'-form',target:x.forms[i%4],native:x.name+' · '+['isolated','initial','medial','final'][i%4]})),types:['choice'],questionCount:10}));document.querySelector('#connect-game')?.addEventListener('click',async()=>startQuiz(c,{items:(await category('ar','nouns')).slice(0,10),types:['scramble'],questionCount:10}));}
const view=()=>document.querySelector('#view');
export async function grammar(c){const lessons=await json(`data/${c.language.code}/grammar.json`),verbs=await category(c.language.code,'verbs');c.register(lessons.flatMap(x=>x.examples));const forms=[];for(const v of verbs){for(const [tense,grid] of Object.entries(v.conjugations||{})){for(const [person,form]of Object.entries(grid)){forms.push({id:`${v.id}-${tense}-${person}`,target:form,native:`${person} · ${v.native} · ${tense}`,category:'verbs',verbId:v.id});}}}c.register(forms);
view().innerHTML=heading('The little things that make it click.',`Short, example-led notes · ${c.language.variety}`)+(c.language.code==='ar'?'<p class="banner">MSA is the default track. Spoken dialects differ in vocabulary, grammar, and pronunciation. Arabic lessons and generated transliterations are marked for native review.</p>':'')+lessons.map((x,i)=>`<details><summary>${i+1}. ${esc(x.title)}</summary><p>${esc(x.body)}</p>${x.examples.map(e=>`<div class="word-row"><span class="word-main">${target(e,c.language)}</span><span class="word-meaning">${esc(e.native)}</span>${audioButtons(e.id)}</div>`).join('')}<button class="button secondary" data-grammar-quiz="${i}" style="margin-top:16px">Try a quick check →</button></details>`).join('')+`<section class="card" style="margin-top:25px"><h2>Put a verb into motion</h2><label class="field">Explore a conjugation<select id="verb-select">${verbs.filter(x=>x.conjugations).map(x=>`<option value="${x.id}">${esc(x.target)} · ${esc(x.native)}</option>`).join('')}</select></label><div id="conjugation"></div></section>`;
for(const b of document.querySelectorAll('[data-grammar-quiz]'))b.onclick=()=>startQuiz(c,{items:lessons[Number(b.dataset.grammarQuiz)].examples,types:['choice','tf','type'],questionCount:3});function conjugate(){const v=verbs.find(x=>x.id===document.querySelector('#verb-select').value);if(!v)return;document.querySelector('#conjugation').innerHTML=Object.entries(v.conjugations).map(([tense,grid])=>`<h3>${esc(tense)}</h3><div class="table-wrap"><table><thead><tr><th>Person</th><th>Form</th><th>Listen</th></tr></thead><tbody>${Object.entries(grid).map(([person,form])=>{const item=forms.find(x=>x.id===`${v.id}-${tense}-${person}`);return `<tr><td>${esc(person)}</td><td>${target(item,c.language)}</td><td>${audioButtons(item.id)}</td></tr>`;}).join('')}</tbody></table></div>`).join('')+'<button class="button secondary" id="quiz-verb" style="margin-top:15px">Quiz this verb →</button>';document.querySelector('#quiz-verb').onclick=()=>startQuiz(c,{items:forms.filter(x=>x.verbId===v.id),types:['choice','type'],direction:'reverse',questionCount:10});}document.querySelector('#verb-select').onchange=conjugate;conjugate();}
export async function settings(c){const s=c.store.state().settings;const select=(id,title,options)=>`<div class="setting"><label for="${id}">${title}</label><select id="${id}" data-setting="${id}">${options.map(([v,label])=>`<option value="${v}" ${String(s[id])===String(v)?'selected':''}>${label}</option>`).join('')}</select></div>`;const toggle=(id,title,note='')=>`<div class="setting"><label for="${id}">${title}${note?`<small>${note}</small>`:''}</label><input id="${id}" data-setting="${id}" type="checkbox" ${s[id]?'checked':''}></div>`;
view().innerHTML=heading('Make yourself at home.','A few small adjustments for the way you like to learn.')+`<div class="settings"><section class="card"><h2>Your study space</h2>${select('theme','Appearance',[['system','Follow device'],['light','Light'],['dark','Dark']])}${select('fontSize','Text size',[[15,'Comfortable'],[17,'Larger'],[19,'Largest']])}${toggle('transliteration','Show pronunciation guides','Arabic guides are provisional and marked for native review.')}${toggle('ipa','Show IPA when provided')}${toggle('diacritics','Show Arabic short vowels')}${toggle('articles','Show Italian article details')}${toggle('strict','Strict spelling','When off, accents, Arabic diacritics, and alef variants are ignored. Small typos receive “Almost” feedback and count as mistakes.')}${toggle('hearts','Hearts mode','Optional. Three mistakes end a quiz early; off by default.')}</section><section class="card" style="margin-top:20px"><h2>A little listening</h2>${select('speed','Speech speed',[[1,'Normal'],[.7,'Slow'],[.5,'Very slow']])}${toggle('autoplay','Automatically pronounce flashcards')}${toggle('sounds','Answer sound effects')}<div class="setting"><label for="voice">${c.language.name} voice<small>Installed local voices work offline. Browser-provided remote voices may need a connection.</small></label><select id="voice" aria-label="Pronunciation voice"></select></div><div class="flex" style="margin-top:17px"><button class="button secondary" id="test-voice">Test voice</button><button class="button secondary" id="download-audio">Download bundled audio for offline</button></div><p class="muted" id="audio-status"></p></section><section class="card" style="margin-top:20px"><h2>A pace that feels good</h2>${select('goal','Minutes each day',[[5,'5 minutes'],[10,'10 minutes'],[20,'20 minutes']])}${select('newLimit','New cards per day',[[5,'5 cards'],[10,'10 cards'],[20,'20 cards'],[50,'50 cards']])}${select('reviewLimit','Maximum reviews per session',[[20,'20 reviews'],[50,'50 reviews'],[100,'100 reviews'],[500,'500 reviews']])}</section><section class="card" style="margin-top:20px"><h2>Your progress belongs to you</h2><p class="muted">No account needed. Export a backup to move to another device or share a copy. Import replaces this device’s progress after confirmation.</p><div class="flex"><button class="button" id="export">Export progress</button><label class="button secondary">Import progress<input class="sr-only" id="import" type="file" accept="application/json,.json"></label><button class="button secondary" id="reset">Reset progress</button></div></section><section class="card" style="margin-top:20px"><h2>Always a little closer</h2><p>Parola uses original study content and self-hosted assets. No analytics, paid APIs, or runtime third-party requests. Once the offline download completes, lessons and your progress remain available without a connection.</p><p class="muted">Recordings stay in this tab and disappear when it closes. Backups include study progress and custom words, not microphone recordings.</p><div class="flex"><a class="button secondary" href="README.md">Read the guide</a><a class="button secondary" href="CREDITS.md">Content & credits</a><button class="button secondary" id="offline-check">Check offline readiness</button></div><p id="offline-status" class="muted"></p></section></div>`;
for(const el of document.querySelectorAll('[data-setting]'))el.onchange=()=>{const value=el.type==='checkbox'?el.checked:['fontSize','goal','newLimit','reviewLimit','speed'].includes(el.id)?Number(el.value):el.value;c.store.settings({[el.id]:value});if(['theme','fontSize'].includes(el.id))c.rerender();};
const update=()=>{const voices=availableVoices(c.language);const el=document.querySelector('#voice');if(!el)return;el.innerHTML=voices.length?voices.map(v=>`<option value="${esc(v.voiceURI)}" ${s.voices[c.language.code]===v.voiceURI?'selected':''}>${esc(v.name)} · ${v.localService?'offline':'may need internet'}</option>`).join(''):'<option>No voice installed for this language</option>';if(!voices.length)document.querySelector('#audio-status').textContent='No voice found yet. Install a voice through device speech settings; Windows: Time & language → Speech. Apple: Accessibility → Spoken Content → Voices. Android: Text-to-speech → voice data.';};document.addEventListener('parola:voices',update);update();updateVoices();document.querySelector('#voice').onchange=e=>{s.voices[c.language.code]=e.target.value;c.store.save();};document.querySelector('#test-voice').onclick=()=>c.audio.speak({id:'test-'+c.language.code,target:c.language.code==='ar'?'مَرْحَبًا، صَبَاحُ الْخَيْرِ':'Buongiorno! Come stai?'},c.language,false,c.toast);document.querySelector('#export').onclick=c.store.exportProgress;document.querySelector('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const text=await file.text();c.store.validateBackup(JSON.parse(text));modal('<h2>Bring your progress here?</h2><p>This replaces progress on this device. Export a backup first if you want to keep the current version.</p><div class="flex"><button class="button secondary" id="backup-first">Export current backup</button><button class="button" id="confirm-import">Replace with imported progress</button></div>');document.querySelector('#backup-first').onclick=c.store.exportProgress;document.querySelector('#confirm-import').onclick=()=>{try{c.store.importProgress(text);document.querySelector('#modal').close();c.go('home');c.rerender();c.toast('Your progress is home.');}catch(error){c.toast(error.message);}};}catch(error){c.toast('Could not import this backup: '+error.message);}};document.querySelector('#reset').onclick=()=>{modal('<h2>Start a new chapter?</h2><p>This removes progress, custom words, and settings from this browser. Export a backup before resetting.</p><button class="button danger" id="confirm-reset">Yes, reset this device</button>');document.querySelector('#confirm-reset').onclick=()=>{c.store.reset();document.querySelector('#modal').close();c.go('home');c.rerender();};};document.querySelector('#download-audio').onclick=async e=>{e.target.disabled=true;const el=document.querySelector('#audio-status');el.textContent='Looking for bundled recordings…';try{const n=await downloadAudio(await allItems(c.language.code),c.language,n=>el.textContent=`${n} recordings saved…`);el.textContent=n?`${n} recordings ready offline.`:'No bundled recordings are included yet. Use an installed offline voice, or generate files using the guide.';}catch(error){el.textContent=error.message;}e.target.disabled=false;};document.querySelector('#offline-check').onclick=async()=>{const names=await caches.keys(),name=names.find(x=>x.startsWith('parola-shell-'));const keys=name?await(await caches.open(name)).keys():[];const controller=navigator.serviceWorker?.controller;document.querySelector('#offline-status').textContent=keys.length&&controller?`${keys.length} local files cached. The app is ready offline; installed speech voices have their own device requirements.`:'Offline setup is still finishing. Keep this page open, then reload and check again.';};return ()=>document.removeEventListener('parola:voices',update);}
